//! Plan 9 character handling used by MediaPipe's text ops (`custom_ops/utils/utf`).
//!
//! The tables predate current Unicode, so `char::is_alphabetic` and `char::to_lowercase`
//! disagree with them on some code points; n-gram hashes need the exact original behavior.

use tables::{ALPHA_RANGES, ALPHA_SINGLES, LOWER_PAIRS, LOWER_RANGES, LOWER_SINGLES};

mod tables {
    // Generated by build.rs from vendor/mediapipe/runetypebody.h.
    include!(concat!(env!("OUT_DIR"), "/unicode_tables.rs"));
}

/// Code point returned for malformed UTF-8 (`Runeerror`).
const REPLACEMENT: u32 = 0xFFFD;

/// Largest code point (`Runemax`).
const MAX: u32 = 0x10_FFFF;

/// `utf_isalpharune`.
pub(crate) fn is_alpha(c: u32) -> bool {
    let in_range = match ALPHA_RANGES.partition_point(|&(start, _)| start <= c) {
        0 => false,
        i => c <= ALPHA_RANGES[i - 1].1,
    };
    in_range || ALPHA_SINGLES.binary_search(&c).is_ok()
}

/// `utf_tolowerrune`.
pub(crate) fn to_lower(c: u32) -> u32 {
    let shift = |delta: i32| c.checked_add_signed(delta).unwrap_or(c);
    if let Some(&(start, end, delta)) = last_starting_at_or_before(LOWER_RANGES, c, |r| r.0)
        && (start..=end).contains(&c)
    {
        return shift(delta);
    }
    if let Some(&(start, end, delta)) = last_starting_at_or_before(LOWER_PAIRS, c, |r| r.0)
        && (start..=end).contains(&c)
        && (c - start).is_multiple_of(2)
    {
        return shift(delta);
    }
    match LOWER_SINGLES.binary_search_by_key(&c, |&(cp, _)| cp) {
        Ok(i) => shift(LOWER_SINGLES[i].1),
        Err(_) => c,
    }
}

fn last_starting_at_or_before<T>(table: &[T], c: u32, start: impl Fn(&T) -> u32) -> Option<&T> {
    match table.partition_point(|row| start(row) <= c) {
        0 => None,
        i => Some(&table[i - 1]),
    }
}

/// Outcome of decoding one character with `utf_charntorune`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Decoded {
    /// A code point (`REPLACEMENT` for malformed input) and the bytes it used.
    Rune(u32, usize),
    /// The input ends in the middle of a character.
    Truncated,
}

/// `utf_charntorune`: decodes the first character of `bytes`.
pub(crate) fn decode(bytes: &[u8]) -> Decoded {
    let Some(&b0) = bytes.first() else {
        return Decoded::Truncated;
    };
    if b0 < 0x80 {
        return Decoded::Rune(u32::from(b0), 1);
    }
    let bad = Decoded::Rune(REPLACEMENT, 1);
    // Payload of continuation byte `i`, or `None` if it is not a continuation byte.
    let cont = |i: usize| -> Option<u32> {
        let b = bytes[i] ^ 0x80;
        (b & 0xC0 == 0).then_some(u32::from(b))
    };
    let lead = u32::from(b0);

    if bytes.len() < 2 {
        return Decoded::Truncated;
    }
    let Some(c1) = cont(1) else { return bad };
    if b0 < 0xE0 {
        if b0 < 0xC0 {
            return bad;
        }
        let rune = ((lead << 6) | c1) & 0x7FF;
        return if rune <= 0x7F { bad } else { Decoded::Rune(rune, 2) };
    }

    if bytes.len() < 3 {
        return Decoded::Truncated;
    }
    let Some(c2) = cont(2) else { return bad };
    if b0 < 0xF0 {
        let rune = ((((lead << 6) | c1) << 6) | c2) & 0xFFFF;
        return if rune <= 0x7FF { bad } else { Decoded::Rune(rune, 3) };
    }

    if bytes.len() < 4 {
        return Decoded::Truncated;
    }
    let Some(c3) = cont(3) else { return bad };
    if b0 < 0xF8 {
        let rune = ((((((lead << 6) | c1) << 6) | c2) << 6) | c3) & 0x1F_FFFF;
        return if rune <= 0xFFFF || rune > MAX {
            bad
        } else {
            Decoded::Rune(rune, 4)
        };
    }
    bad
}

/// `utf_runetochar`: appends the UTF-8 encoding of `rune`, or of U+FFFD if it is not a
/// valid code point.
pub(crate) fn encode(rune: u32, out: &mut Vec<u8>) {
    let c = char::from_u32(rune).unwrap_or(char::REPLACEMENT_CHARACTER);
    let mut buf = [0; 4];
    out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn letters_are_alphabetic_and_the_rest_is_not() {
        for c in ['a', 'Z', 'é', 'Ж', 'あ', '中', 'ß'] {
            assert!(is_alpha(u32::from(c)), "{c}");
        }
        for c in [' ', '1', '!', '😀', '٣', '\u{0}'] {
            assert!(!is_alpha(u32::from(c)), "{c:?}");
        }
    }

    #[test]
    fn lowercases_like_plan9() {
        let lower = |c: char| char::from_u32(to_lower(u32::from(c))).unwrap();
        // Cases from MediaPipe's ngram_hash_ops_utils_test.cc.
        assert_eq!(lower('E'), 'e');
        assert_eq!(lower('Б'), 'б');
        assert_eq!(lower('Й'), 'й');
        assert_eq!(lower('あ'), 'あ');
        // Alternating ranges only map their even offsets (Ā -> ā, ā stays).
        assert_eq!(lower('Ā'), 'ā');
        assert_eq!(lower('ā'), 'ā');
        // Turkish dotted capital I loses its dot, unlike Unicode's full mapping.
        assert_eq!(lower('İ'), 'i');
        assert_eq!(lower('1'), '1');
    }

    #[test]
    fn decodes_valid_and_malformed_utf8() {
        for c in ['a', 'é', 'ж', '中', '😀'] {
            let mut buf = [0; 4];
            let bytes = c.encode_utf8(&mut buf).as_bytes();
            assert_eq!(decode(bytes), Decoded::Rune(u32::from(c), bytes.len()));
            if bytes.len() > 1 {
                assert_eq!(decode(&bytes[..bytes.len() - 1]), Decoded::Truncated);
            }
        }
        // A stray continuation byte is malformed, unless it is the last byte (truncated).
        assert_eq!(decode(&[0x80, 0x80]), Decoded::Rune(REPLACEMENT, 1));
        assert_eq!(decode(&[0x80]), Decoded::Truncated);
        assert_eq!(decode(&[0xC3, 0x41]), Decoded::Rune(REPLACEMENT, 1));
        assert_eq!(decode(&[]), Decoded::Truncated);
    }
}
